export interface TournamentStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export interface TournamentHistoryRead {
  readonly tournaments: readonly Tournament[];
  readonly available: boolean;
}

export function browserTournamentStore(): TournamentStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

export function readTournamentHistory(store: TournamentStore | null): TournamentHistoryRead {
  if (!store) return { tournaments: [], available: false };
  try {
    const text = store.getItem(TOURNAMENTS_KEY);
    if (text === null) return { tournaments: [], available: true };
    return { tournaments: decodeTournamentHistory(text) ?? [], available: true };
  } catch {
    return { tournaments: [], available: false };
  }
}

export function writeTournamentHistory(
  store: TournamentStore | null,
  tournaments: readonly Tournament[],
): boolean {
  if (!store) return false;
  try {
    store.setItem(TOURNAMENTS_KEY, encodeTournamentHistory(tournaments));
    return true;
  } catch {
    return false;
  }
}
import { isJsonObject, parseJson } from '../saved-format.ts';

const EVENT_KEYS = [
  'createdAt', 'currentMatchIndex', 'currentTurn', 'finishedAt', 'game', 'gameElapsedMs',
  'kind', 'matches', 'phase', 'playerCount', 'players',
];
const MATCH_KEYS = [
  'advanceTo', 'boardCode', 'number', 'playerSeeds', 'results', 'round', 'size', 'winnerSeed',
];

export function unknownTournamentField(text: string): string | null {
  const root = parseJson(text);
  if (!isJsonObject(root)) return null;
  const rootField = unknownKey(root, ['data', 'format', 'version']);
  if (rootField) return rootField;
  if (!isJsonObject(root.data)) return null;
  if (root.data.kind === 'setup') return unknownKey(root.data, ['kind', 'names', 'playerCount']);
  if (root.data.kind !== 'event') return null;
  const eventField = unknownKey(root.data, EVENT_KEYS);
  if (eventField) return eventField;
  if (Array.isArray(root.data.players)) {
    for (const player of root.data.players) {
      const field = isJsonObject(player) ? unknownKey(player, ['name', 'seed']) : null;
      if (field) return field;
    }
  }
  if (Array.isArray(root.data.matches)) {
    for (const match of root.data.matches) {
      const field = scanMatch(match);
      if (field) return field;
    }
  }
  if (isJsonObject(root.data.game)) return scanGame(root.data.game);
  return null;
}

function scanMatch(value: unknown): string | null {
  if (!isJsonObject(value)) return null;
  const field = unknownKey(value, MATCH_KEYS);
  if (field) return field;
  if (isJsonObject(value.advanceTo)) {
    const nested = unknownKey(value.advanceTo, ['matchIndex', 'slot']);
    if (nested) return nested;
  }
  if (Array.isArray(value.results)) {
    for (const result of value.results) {
      if (!isJsonObject(result)) continue;
      const nested = unknownKey(result, ['elapsedMs', 'moves']);
      if (nested) return nested;
    }
  }
  return null;
}

function scanGame(value: Record<string, unknown>): string | null {
  const field = unknownKey(value, [
    'boardCode', 'elapsedMs', 'matched', 'moves', 'selection', 'started', 'version',
  ]);
  if (field || !isJsonObject(value.selection)) return field;
  const kind = value.selection.kind;
  const fields = kind === 'one'
    ? ['index', 'kind']
    : kind === 'mismatch'
      ? ['first', 'kind', 'remainingMs', 'second']
      : ['kind'];
  return unknownKey(value.selection, fields);
}

function unknownKey(value: Record<string, unknown>, allowed: readonly string[]): string | null {
  return Object.keys(value).find((key) => !allowed.includes(key)) ?? null;
}
import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { parseEvent, serializeEvent } from './event-format.ts';
import type { Tournament } from './rules.ts';

export const TOURNAMENTS_KEY = 'np3:tournaments';
export const TOURNAMENT_FILE_FORMAT = 'neon-pairs/tournament';
export const TOURNAMENT_FILE_VERSION = 1;
export const TOURNAMENT_HISTORY_VERSION = 3;
export const TOURNAMENT_HISTORY_LIMIT = 10;
export const TOURNAMENT_JSON_MAX_BYTES = 262_144;

export interface TournamentDraft {
  readonly playerCount: 4 | 8;
  readonly names: readonly string[];
}

export type TournamentLoad =
  | { readonly kind: 'setup'; readonly draft: TournamentDraft }
  | { readonly kind: 'event'; readonly tournament: Tournament };

export function encodeTournamentFile(
  tournament: Tournament | null,
  draft: TournamentDraft,
): string {
  const data = tournament ? serializeEvent(tournament) : serializeDraft(draft);
  return JSON.stringify(
    { data, format: TOURNAMENT_FILE_FORMAT, version: TOURNAMENT_FILE_VERSION },
    null,
    2,
  );
}

export function decodeTournamentFile(text: string): TournamentLoad | null {
  if (!isWithinBytes(text, TOURNAMENT_JSON_MAX_BYTES)) return null;
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['data', 'format', 'version']) ||
    value.format !== TOURNAMENT_FILE_FORMAT ||
    value.version !== TOURNAMENT_FILE_VERSION ||
    !isJsonObject(value.data)
  )
    return null;
  if (value.data.kind === 'event') {
    const tournament = parseEvent(value.data);
    return tournament ? { kind: 'event', tournament } : null;
  }
  return readDraft(value.data);
}

export function encodeTournamentHistory(tournaments: readonly Tournament[]): string {
  return JSON.stringify({
    items: tournaments.slice(0, TOURNAMENT_HISTORY_LIMIT).map(serializeEvent),
    v: TOURNAMENT_HISTORY_VERSION,
  });
}

export function decodeTournamentHistory(text: string): readonly Tournament[] | null {
  if (!isWithinBytes(text, TOURNAMENT_JSON_MAX_BYTES)) return null;
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['items', 'v']) ||
    value.v !== TOURNAMENT_HISTORY_VERSION ||
    !Array.isArray(value.items) ||
    value.items.length > TOURNAMENT_HISTORY_LIMIT
  )
    return null;
  const tournaments: Tournament[] = [];
  for (const item of value.items) {
    const tournament = parseEvent(item);
    if (!tournament || tournament.phase !== 'finished') return null;
    tournaments.push(tournament);
  }
  return tournaments;
}

function serializeDraft(draft: TournamentDraft): Record<string, unknown> {
  return { kind: 'setup', names: draft.names.slice(0, 8), playerCount: draft.playerCount };
}

function readDraft(value: Record<string, unknown>): TournamentLoad | null {
  if (!hasExactKeys(value, ['kind', 'names', 'playerCount']) || value.kind !== 'setup') return null;
  if (
    (value.playerCount !== 4 && value.playerCount !== 8) ||
    !Array.isArray(value.names) ||
    value.names.length !== 8 ||
    !value.names.every((name) => typeof name === 'string' && Array.from(name).length <= 100)
  )
    return null;
  return {
    kind: 'setup',
    draft: { playerCount: value.playerCount, names: value.names },
  };
}

import assert from 'node:assert/strict';
import { test } from 'vitest';
import { activateCard, advanceGame } from '../game.ts';
import { boardCode } from '../deck.ts';
import {
  decodeTournamentFile,
  decodeTournamentHistory,
  encodeTournamentFile,
  encodeTournamentHistory,
} from './format.ts';
import { beginTurn, createTournament } from './rules.ts';
import type { Entrant } from './rules.ts';

const PLAYERS: Entrant[] = ['Ada', 'Bo', 'Cora', 'Dev'].map((name, index) => ({
  seed: index + 1,
  name,
}));
const CODES = [boardCode(6, 1), boardCode(6, 2), boardCode(8, 3)];

test('setup drafts round trip without treating incomplete input as accepted names', () => {
  const draft = { playerCount: 4 as const, names: ['Ada', '', 'Cora', 'Dev', '', '', '', ''] };
  const loaded = decodeTournamentFile(encodeTournamentFile(null, draft));
  assert.deepEqual(loaded, { kind: 'setup', draft });
});

test('active tournaments round trip the board and fractional active time', () => {
  let tournament = createTournament(PLAYERS, CODES, '2026-11-05T11:00:00.000Z');
  tournament = beginTurn(tournament);
  const first = activateCard(tournament.currentGame!, 0);
  tournament = { ...tournament, currentGame: advanceGame(first, 12.5) };
  const loaded = decodeTournamentFile(
    encodeTournamentFile(tournament, { playerCount: 4, names: [] }),
  );
  assert.equal(loaded?.kind, 'event');
  if (loaded?.kind !== 'event') throw new Error('Expected an active event.');
  assert.equal(loaded.tournament.currentGame?.boardCode, CODES[0]);
  assert.equal(loaded.tournament.currentGame?.elapsedMs, 12.5);
  assert.deepEqual(loaded.tournament.currentGame?.selection, { kind: 'one', index: 0 });
});

test('imports reject unknown fields and repeated match deal codes', () => {
  const event = beginTurn(createTournament(PLAYERS, CODES, '2026-11-05T11:00:00.000Z'));
  const base = JSON.parse(encodeTournamentFile(event, { playerCount: 4, names: [] })) as {
    data: Record<string, unknown>;
  };
  const withExtra = structuredClone(base);
  withExtra.data.extra = true;
  assert.equal(decodeTournamentFile(JSON.stringify(withExtra)), null);
  const withRepeatedCode = structuredClone(base);
  const matches = withRepeatedCode.data.matches as Array<Record<string, unknown>>;
  matches[1]!.boardCode = matches[0]!.boardCode;
  assert.equal(decodeTournamentFile(JSON.stringify(withRepeatedCode)), null);
});

test('tournament history uses a bounded versioned envelope', () => {
  const encoded = encodeTournamentHistory([]);
  assert.deepEqual(decodeTournamentHistory(encoded), []);
  assert.equal(decodeTournamentHistory('{'), null);
  assert.equal(
    decodeTournamentHistory(JSON.stringify({ schemaVersion: 1, tournaments: [null] })),
    null,
  );
});
