import { ELAPSED_MAX_MS, isWon } from '../game.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  parseJson,
} from '../saved-format.ts';
import { isBracketValid, isProgressValid, readMatches, readPlayers } from './event-shapes.ts';
import type { Tournament, TournamentMatch, TournamentPhase, TournamentResult } from './rules.ts';
import type { GameState } from '../game.ts';

const EVENT_KEYS = [
  'kind',
  'playerCount',
  'players',
  'matches',
  'currentMatchIndex',
  'currentTurn',
  'phase',
  'createdAt',
  'finishedAt',
  'game',
  'gameElapsedMs',
];

export function serializeEvent(tournament: Tournament): Record<string, unknown> {
  return {
    createdAt: tournament.createdAt,
    currentMatchIndex: tournament.currentMatchIndex,
    currentTurn: tournament.currentTurn,
    finishedAt: tournament.finishedAt,
    game: tournament.currentGame ? serializeGame(tournament.currentGame) : null,
    gameElapsedMs: tournament.currentGame?.elapsedMs ?? null,
    kind: 'event',
    matches: tournament.matches.map((match) => ({
      advanceTo: match.advanceTo
        ? { matchIndex: match.advanceTo.matchIndex, slot: match.advanceTo.slot }
        : null,
      boardCode: match.boardCode,
      number: match.number,
      playerSeeds: match.playerSeeds,
      results: match.results.map((result) =>
        result ? { elapsedMs: result.elapsedMs, moves: result.moves } : null,
      ),
      round: match.round,
      size: match.size,
      winnerSeed: match.winnerSeed,
    })),
    phase: tournament.phase,
    playerCount: tournament.playerCount,
    players: tournament.players.map((player) => ({ name: player.name, seed: player.seed })),
  };
}

export function parseEvent(value: unknown): Tournament | null {
  if (!isJsonObject(value) || !hasExactKeys(value, EVENT_KEYS) || value.kind !== 'event')
    return null;
  const count = value.playerCount;
  if (count !== 4 && count !== 8) return null;
  const players = readPlayers(value.players, count);
  const matches = readMatches(value.matches, count);
  const index = value.currentMatchIndex;
  const turn = value.currentTurn;
  const phase = readPhase(value.phase);
  if (
    !players ||
    !matches ||
    !isNonnegativeSafeInteger(index) ||
    index >= matches.length ||
    (turn !== 0 && turn !== 1) ||
    !phase ||
    !isIsoDate(value.createdAt)
  )
    return null;
  const finishedAt = value.finishedAt;
  if (finishedAt !== null && !isIsoDate(finishedAt)) return null;
  if (!isBracketValid(matches, count) || !isProgressValid(matches, index, turn, phase, finishedAt))
    return null;
  const match = matches[index];
  if (!match) return null;
  const game = readCurrentGame(value.game, value.gameElapsedMs, phase, match, match.results[turn]);
  if (game === undefined) return null;
  return {
    playerCount: count,
    players,
    matches,
    currentMatchIndex: index,
    currentTurn: turn,
    phase,
    currentGame: game,
    createdAt: value.createdAt,
    finishedAt,
  };
}

function readCurrentGame(
  snapshot: unknown,
  elapsedMs: unknown,
  phase: TournamentPhase,
  match: TournamentMatch,
  result: TournamentResult | null,
) {
  if (phase !== 'playing' && phase !== 'turnComplete')
    return snapshot === null && elapsedMs === null ? null : undefined;
  if (
    !isJsonObject(snapshot) ||
    typeof elapsedMs !== 'number' ||
    !Number.isFinite(elapsedMs) ||
    elapsedMs < 0 ||
    elapsedMs > ELAPSED_MAX_MS
  )
    return undefined;
  const decoded = decodeSnapshot(JSON.stringify(snapshot));
  if (
    !decoded ||
    decoded.boardCode !== match.boardCode ||
    elapsedMs < decoded.elapsedMs ||
    elapsedMs >= decoded.elapsedMs + 1
  )
    return undefined;
  const game = { ...decoded, elapsedMs };
  if (phase === 'playing' && isWon(game)) return undefined;
  if (
    phase === 'turnComplete' &&
    (!isWon(game) || !result || result.moves !== game.moves || result.elapsedMs !== game.elapsedMs)
  )
    return undefined;
  return game;
}

function serializeGame(game: GameState) {
  const snapshot = parseJson(encodeSnapshot(game));
  if (!isJsonObject(snapshot)) throw new Error('Invalid game snapshot.');
  const selection = snapshot.selection;
  if (!isJsonObject(selection)) throw new Error('Invalid game selection.');
  const kind = selection.kind;
  const orderedSelection =
    kind === 'one'
      ? { index: selection.index, kind }
      : kind === 'mismatch'
        ? {
            first: selection.first,
            kind,
            remainingMs: selection.remainingMs,
            second: selection.second,
          }
        : { kind };
  return {
    boardCode: snapshot.boardCode,
    elapsedMs: snapshot.elapsedMs,
    matched: snapshot.matched,
    moves: snapshot.moves,
    selection: orderedSelection,
    started: snapshot.started,
    version: snapshot.version,
  };
}

function readPhase(value: unknown): TournamentPhase | null {
  return value === 'ready' ||
    value === 'playing' ||
    value === 'turnComplete' ||
    value === 'finished'
    ? value
    : null;
}

function isIsoDate(value: unknown): value is string {
  if (typeof value !== 'string') return false;
  const date = new Date(value);
  return Number.isFinite(date.getTime()) && date.toISOString() === value;
}
import { decodeTournamentHistory, encodeTournamentHistory, TOURNAMENTS_KEY } from './format.ts';
import type { Tournament } from './rules.ts';

export interface TournamentStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export interface TournamentHistoryRead {
  readonly tournaments: readonly Tournament[];
  readonly available: boolean;
}

export function browserTournamentStore(): TournamentStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

export function readTournamentHistory(store: TournamentStore | null): TournamentHistoryRead {
  if (!store) return { tournaments: [], available: false };
  try {
    const text = store.getItem(TOURNAMENTS_KEY);
    if (text === null) return { tournaments: [], available: true };
    return { tournaments: decodeTournamentHistory(text) ?? [], available: true };
  } catch {
    return { tournaments: [], available: false };
  }
}

export function writeTournamentHistory(
  store: TournamentStore | null,
  tournaments: readonly Tournament[],
): 'saved' | 'unavailable' {
  if (!store) return 'unavailable';
  try {
    store.setItem(TOURNAMENTS_KEY, encodeTournamentHistory(tournaments));
    return 'saved';
  } catch {
    return 'unavailable';
  }
}
import { useRef, useState } from 'react';
import { activateCard, isWon } from '../game.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { decodeTournamentFile, encodeTournamentFile, TOURNAMENT_HISTORY_LIMIT } from './format.ts';
import { matchPlans } from './pairing.ts';
import { beginTurn, createTournament, finishTurn, nextMatch, nextTurn } from './rules.ts';
import {
  browserTournamentStore,
  readTournamentHistory,
  writeTournamentHistory,
} from './storage.ts';
import { useTournamentClock } from './use-tournament-clock.ts';
import { unknownTournamentField } from './unknown-field.ts';
import type { Tournament } from './rules.ts';
import type { Entrant, PlayerCount } from './rules.ts';
import type { TournamentDraft, TournamentLoad } from './format.ts';

export const TournamentNotice = {
  invalid: 'Invalid tournament JSON.',
  loaded: 'Tournament loaded.',
  saved: 'Tournament saved in Past tournaments.',
} as const;

export function useTournament(enabled = true) {
  const [store] = useState(browserTournamentStore);
  const [initialHistory] = useState(() => readTournamentHistory(store));
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const current = useRef(tournament);
  const past = useRef(initialHistory.tournaments);
  const [pastTournaments, setPastTournaments] = useState(initialHistory.tournaments);
  const [storageAvailable, setStorageAvailable] = useState(initialHistory.available);
  const [notice, setNotice] = useState('');

  function recordCompleted(completed: Tournament): boolean {
    const code = completed.matches[0]?.boardCode ?? '';
    if (
      past.current.some(
        (item) => item.createdAt === completed.createdAt && item.matches[0]?.boardCode === code,
      )
    )
      return true;
    const next = [completed, ...past.current].slice(0, TOURNAMENT_HISTORY_LIMIT);
    past.current = next;
    setPastTournaments(next);
    const saved = writeTournamentHistory(store, next);
    if (saved === 'unavailable') setStorageAvailable(false);
    return saved === 'saved';
  }

  function commit(next: Tournament | null): void {
    const previous = current.current;
    if (next === previous) return;
    current.current = next;
    setTournament(next);
    if (next?.phase === 'finished' && previous?.phase !== 'finished') {
      const saved = recordCompleted(next);
      const winner = next.players.find((player) => player.seed === next.matches.at(-1)?.winnerSeed);
      setNotice(
        saved
          ? `${TournamentNotice.saved} Champion: ${winner?.name ?? ''}`
          : `Tournament finished. Champion: ${winner?.name ?? ''}`,
      );
    }
  }

  const clock = useTournamentClock(tournament, current, commit, enabled);

  function startTournament(names: readonly string[], playerCount: PlayerCount): void {
    const players: Entrant[] = names.map((name, index) => ({ seed: index + 1, name }));
    const used = new Set<string>();
    const codes = matchPlans(playerCount).map((plan) => {
      let code = freshBoardCode(plan.size);
      while (used.has(code)) code = freshBoardCode(plan.size);
      used.add(code);
      return code;
    });
    clock.reset();
    setNotice('');
    commit(createTournament(players, codes, new Date().toISOString()));
  }

  function startTurn(): void {
    const active = current.current;
    if (!active) return;
    clock.reset();
    commit(beginTurn(active));
  }

  function activate(index: number): void {
    clock.synchronize();
    const active = current.current;
    const game = active?.currentGame;
    if (!active || active.phase !== 'playing' || !game) return;
    const nextGame = activateCard(game, index);
    if (nextGame === game) return;
    if (isWon(nextGame)) {
      const next = finishTurn(active, nextGame, new Date().toISOString());
      commit(next);
      if (next.phase === 'turnComplete') setNotice('Turn complete.');
    } else commit({ ...active, currentGame: nextGame });
  }

  function advanceToNextTurn(): void {
    const active = current.current;
    if (!active) return;
    clock.reset();
    commit(nextTurn(active));
    setNotice('');
  }

import type { PlayerCount, TournamentRound } from './rules.ts';

interface MatchPlan {
  readonly round: TournamentRound;
  readonly number: number;
