        value={text}
        onChange={(event) => setText(event.currentTarget.value)}
      />
      <div className="tournament-actions">
        <button className="control" type="button" onClick={exportJson}>
          Export tournament
        </button>
        <button className="control" type="button" onClick={loadJson}>
