}

    const used = new Set<string>();
    const codes = matchPlans(playerCount).map((plan) => {
      let code = freshBoardCode(plan.size);
      while (used.has(code)) code = freshBoardCode(plan.size);
      used.add(code);
      return code;
    });
    clock.reset();
    setNotice('');
    commit(createTournament(players, codes, new Date().toISOString()));
  }

  function startTurn(): void {
    const active = current.current;
    if (!active) return;
    clock.reset();
    commit(beginTurn(active));
  }

  function activate(index: number): void {
    clock.synchronize();
    const active = current.current;
    const game = active?.currentGame;
    if (!active || active.phase !== 'playing' || !game) return;
    const nextGame = activateCard(game, index);
    if (nextGame === game) return;
    if (isWon(nextGame)) {
      const next = finishTurn(active, nextGame, new Date().toISOString());
      commit(next);
      if (next.phase === 'turnComplete') setNotice('Turn complete.');
    } else commit({ ...active, currentGame: nextGame });
  }

  function advanceToNextTurn(): void {
    const active = current.current;
    if (!active) return;
    clock.reset();
    commit(nextTurn(active));
    setNotice('');
  }

  function advanceToNextMatch(): void {
    const active = current.current;
    if (!active) return;
    clock.reset();
    commit(nextMatch(active));
    setNotice('');
  }

  function loadTournament(text: string): TournamentLoad | null {
    const loaded = decodeTournamentFile(text);
    if (!loaded) {
      const field = unknownTournamentField(text);
      setNotice(field ? `Unknown field: ${field}.` : TournamentNotice.invalid);
      return null;
    }
    clock.reset();
    setNotice(
      loaded.kind === 'event' &&
        (loaded.tournament.phase === 'ready' || loaded.tournament.phase === 'playing')
        ? ''
        : TournamentNotice.loaded,
    );
    if (loaded.kind === 'setup') commit(null);
    else {
      commit(loaded.tournament);
      if (loaded.tournament.phase === 'finished') recordCompleted(loaded.tournament);
    }
    return loaded;
  }

  function exportTournament(draft: TournamentDraft): string {
    return encodeTournamentFile(current.current ?? past.current[0] ?? null, draft);
  }

  return {
    tournament,
    pastTournaments,
    storageAvailable,
    notice,
    startTournament,
    startTurn,
    activate,
    advanceToNextTurn,
    advanceToNextMatch,
    loadTournament,
    exportTournament,
    synchronizeClock: clock.synchronize,
    resetClock: clock.reset,
    clearNotice: () => setNotice(''),
  };
}
import { useEffect, useRef } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { GameStatus } from '../status/GameStatus.tsx';
import { Bracket } from './Bracket.tsx';
import { champion, currentMatch } from './rules.ts';
import type { Tournament } from './rules.ts';

interface TournamentLiveProps {
  tournament: Tournament;
  startTurn(): void;
  activate(index: number): void;
  nextTurn(): void;
  nextMatch(): void;
  onBack(): void;
}

export function TournamentLive({
  tournament,
  startTurn,
  activate,
  nextTurn,
  nextMatch,
  onBack,
}: TournamentLiveProps) {
  const winner = champion(tournament);
  const match = currentMatch(tournament);
  const game = tournament.currentGame;
  const board = useRef<BoardFocus>(null);
  useEffect(() => {
    if (tournament.phase === 'playing') board.current?.focusRemembered();
  }, [tournament.currentMatchIndex, tournament.currentTurn, tournament.phase]);
  return (
    <div className="tournament-live">
      {winner ? (
        <div className="tournament-champion">
          <h3>Champion: {winner.name}</h3>
          <button className="control" type="button" onClick={onBack}>
            Back to game
          </button>
        </div>
      ) : (
        <>
          <p className="tournament-round">Round: {match.round}</p>
          {tournament.phase === 'ready' && (
            <button className="control" type="button" onClick={startTurn}>
              Start turn
            </button>
          )}
          {tournament.phase === 'turnComplete' && (
            <button
              className="control"
              type="button"
              onClick={tournament.currentTurn === 0 ? nextTurn : nextMatch}
            >
              {tournament.currentTurn === 0 ? 'Next turn' : 'Next match'}
            </button>
          )}
          {game && (
            <>
              <GameStatus game={game} best={undefined} celebration={false} showBest={false} />
              <p id="board-help" className="help">
                Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or
                Space reveals a card.
              </p>
              <Board
                key={`${tournament.currentMatchIndex}-${tournament.currentTurn}`}
                game={game}
                activate={activate}
                ref={board}
              />
            </>
          )}
        </>
      )}
      <Bracket tournament={tournament} />
    </div>
  );
}
